#!/usr/bin/env python3
"""dock/covalent_docking — auto-generated run.py (archetype=docking).

第一版只实现 simulate 模式:从 stdin/args 拿 inputs,产合理合成数据 JSON。
真实现路径(simulate=False)留 stub:返回 not-implemented + 提示。

输入契约:
  stdin JSON,字段按 SKILL.md 的 inputs 段;simulate 默认 true。
  CLI 兜底:--simulate / 各位置参数。

输出:
  stdout JSON;失败时也写 JSON {"ok": false, "error": "..."} 而非裸 traceback。
"""
import json
import sys

ARCHETYPE = "docking"
BRAIN = "dock"
SKILL = "covalent_docking"

def simulate(payload):
    """auto-generated by regen_simulate.py — outputs schema 来自 SKILL.md."""
    import copy
    import random
    random.seed(int(payload.get("seed", 42)) if isinstance(payload, dict) else 42)
    out = copy.deepcopy({'skill_id': 'covalent_docking', 'receptor': '', 'ligand': '', 'best_affinity': 0.0, 'poses': [{'rank': 1, 'affinity_kcal_per_mol': 0.0, 'pose_path': ''}], 'runtime_sec': 0.0, 'diagnostics': {'brain': 'dock', 'archetype': 'docking'}})
    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({
                "simulated": True,
                "archetype": ARCHETYPE,
                "brain": BRAIN,
                "skill": SKILL,
            })
        if "skill_id" in out and not out["skill_id"]:
            out["skill_id"] = SKILL
    return out

def real(payload):
    """简化共价 docking:vina dock + 后过滤(只保留 ligand 反应原子距离 cys_thiol < 2.5Å 的 pose)。

    真正的共价 docking 需要 AutoDock-FR / GOLD covalent / Glide Covalent;
    host praxis-dock env 有 gnina(含 vina 打分引擎),故走"docking + 距离约束筛选"近似。
    输入:receptor_pdb / ligand_sdf(含反应中心标记)/ warhead_smarts / target_residue(如 CYS:145:SG)/
          distance_cutoff_A(默认 2.5)
    """
    import os as _os
    import tempfile as _tempfile
    import time as _time
    try:
        from brains._common.lib.run_tool import run_tool
    except ImportError:
        import sys as _sys
        _sys.path.insert(0, "/home/zkyd/data1/mzy/praxis2-brains")
        from _common.lib.run_tool import run_tool  # noqa: F401

    receptor = payload.get("receptor_pdb")
    ligand_sdf = payload.get("ligand_sdf") or payload.get("ligand")
    warhead_smarts = payload.get("warhead_smarts", "[C:1](=O)")  # 默认 Michael acceptor
    target_residue = payload.get("target_residue", "CYS:145:SG")
    distance_cutoff = float(payload.get("distance_cutoff_A", 2.5))
    n_modes = int(payload.get("num_modes", 20))
    exhaustiveness = int(payload.get("exhaustiveness", 16))

    diagnostics = {"brain": BRAIN, "skill": SKILL, "archetype": ARCHETYPE,
                   "warhead": warhead_smarts, "target_residue": target_residue,
                   "distance_cutoff_A": distance_cutoff,
                   "method": "gnina (vina scoring) + warhead-distance post-filter (simplified)"}

    if _os.environ.get("PRAXIS_SKILL_DRY_HOST") == "1":
        return {"ok": True, "skill_id": SKILL,
                "receptor": receptor or "", "ligand": ligand_sdf or "",
                "best_affinity": 0.0,
                "poses": [{"rank": 1, "affinity_kcal_per_mol": 0.0, "pose_path": ""}],
                "n_covalent_compatible_poses": 0,
                "runtime_sec": 0.0,
                "diagnostics": {**diagnostics, "dry": True}}

    if not receptor or not _os.path.isfile(receptor):
        return {"ok": False, "error": f"receptor_pdb 不存在: {receptor!r}", "diagnostics": diagnostics}
    if not ligand_sdf or not _os.path.isfile(ligand_sdf):
        return {"ok": False, "error": f"ligand_sdf 不存在: {ligand_sdf!r}", "diagnostics": diagnostics}

    out_dir = payload.get("out_dir") or _tempfile.mkdtemp(prefix="cov_dock_")
    diagnostics["out_dir"] = out_dir
    t0 = _time.time()
    out_sdf = _os.path.join(out_dir, "docked.sdf")

    # host 有 gnina(vina 引擎超集),用 --cnn_scoring none 走纯 Vina 打分(快,无需 CNN GPU);
    # gnina 兼容 --autobox_ligand/--num_modes/--out SDF 与 vina 相同 flag。
    dock_cmd = ["gnina", "--receptor", receptor, "--ligand", ligand_sdf,
                "--autobox_ligand", ligand_sdf,
                "--exhaustiveness", str(exhaustiveness), "--num_modes", str(n_modes),
                "--cnn_scoring", "none", "--out", out_sdf]
    r = run_tool(dock_cmd, timeout=int(payload.get("timeout_s", 1200)))
    diagnostics["subprocess"] = {"cmd": r.get("cmd")[:200], "wall_sec": r.get("wall_sec"), "rc": r.get("returncode")}
    if not r["ok"]:
        return {"ok": False, "error": r.get("error", "vina 调用失败"),
                "stderr": r.get("stderr", "")[-400:], "diagnostics": diagnostics}

    # 解析 vina stdout 拿 affinity;同时算每个 pose 反应中心到 target_residue 的距离
    poses_aff = []
    for ln in r["stdout"].splitlines():
        parts = ln.split()
        if len(parts) >= 4 and parts[0].isdigit():
            try:
                poses_aff.append({"rank": int(parts[0]), "affinity_kcal_per_mol": float(parts[1])})
            except ValueError:
                continue

    # 后过滤:用 RDKit + Bio.PDB 算每个 pose 的反应原子到 target_residue 距离
    filter_script = (
        "import json, sys\n"
        "from rdkit import Chem\n"
        "from rdkit.Chem import AllChem\n"
        "try:\n"
        "    from Bio.PDB import PDBParser\n"
        "    bio_ok = True\n"
        "except Exception:\n"
        "    bio_ok = False\n"
        f"out_sdf = {out_sdf!r}; receptor = {receptor!r}\n"
        f"warhead_smarts = {warhead_smarts!r}; target_residue = {target_residue!r}\n"
        f"distance_cutoff = {distance_cutoff}\n"
        "patt = Chem.MolFromSmarts(warhead_smarts)\n"
        "poses = list(Chem.SDMolSupplier(out_sdf, removeHs=False))\n"
        "if not bio_ok:\n"
        "    json.dump({'compat': [{'idx': i} for i in range(len(poses))], 'n_compat': len(poses), 'method': 'no-bio'}, sys.stdout)\n"
        "    sys.exit(0)\n"
        "parser = PDBParser(QUIET=True)\n"
        "struct = parser.get_structure('r', receptor)\n"
        "rn, ri, atm = target_residue.split(':')\n"
        "tgt_coord = None\n"
        "for atom in struct.get_atoms():\n"
        "    res = atom.get_parent()\n"
        "    if res.get_resname() == rn and str(res.get_id()[1]) == ri and atom.get_id() == atm:\n"
        "        tgt_coord = atom.get_coord(); break\n"
        "compat = []\n"
        "for i, m in enumerate(poses):\n"
        "    if m is None: continue\n"
        "    if patt is None: compat.append({'idx': i, 'dist_A': None}); continue\n"
        "    matches = m.GetSubstructMatches(patt)\n"
        "    if not matches: continue\n"
        "    rxn_atom_idx = matches[0][0]\n"
        "    conf = m.GetConformer()\n"
        "    rxn_xyz = conf.GetAtomPosition(rxn_atom_idx)\n"
        "    if tgt_coord is None: continue\n"
        "    dx = rxn_xyz.x - float(tgt_coord[0]); dy = rxn_xyz.y - float(tgt_coord[1]); dz = rxn_xyz.z - float(tgt_coord[2])\n"
        "    dist = (dx*dx + dy*dy + dz*dz) ** 0.5\n"
        "    if dist <= distance_cutoff:\n"
        "        compat.append({'idx': i, 'dist_A': round(dist, 2)})\n"
        "json.dump({'compat': compat, 'n_compat': len(compat), 'method': 'bio-distance'}, sys.stdout)\n"
    )
    rf = run_tool(["python3", "-c", filter_script], timeout=60)
    n_compat = 0
    compat_idx_to_dist = {}
    if rf["ok"]:
        try:
            j = json.loads(rf["stdout"])
            n_compat = j.get("n_compat", 0)
            for it in j.get("compat", []):
                compat_idx_to_dist[it["idx"]] = it.get("dist_A")
            diagnostics["filter_method"] = j.get("method")
        except json.JSONDecodeError:
            diagnostics["filter_error"] = rf["stdout"][:200]

    enriched_poses = []
    for i, p in enumerate(poses_aff):
        p["pose_path"] = out_sdf
        if i in compat_idx_to_dist:
            p["covalent_compatible"] = True
            p["warhead_dist_A"] = compat_idx_to_dist[i]
        enriched_poses.append(p)

    best_aff = enriched_poses[0]["affinity_kcal_per_mol"] if enriched_poses else 0.0
    return {"ok": True, "skill_id": SKILL,
            "receptor": receptor, "ligand": ligand_sdf,
            "best_affinity": best_aff,
            "poses": enriched_poses,
            "n_covalent_compatible_poses": n_compat,
            "runtime_sec": round(_time.time() - t0, 2),
            "diagnostics": diagnostics}

def main():
    # stdin 优先(SkillExecTool 走 stdin)
    payload = {}
    if not sys.stdin.isatty():
        try:
            payload = json.load(sys.stdin)
            if not isinstance(payload, dict):
                payload = {}
        except json.JSONDecodeError:
            payload = {}
    if not payload:
        # 简易 CLI 兜底
        import argparse
        ap = argparse.ArgumentParser()
        ap.add_argument("--simulate", action="store_true", default=True)
        ap.add_argument("--seed", type=int, default=42)
        args, _ = ap.parse_known_args()
        payload = {"simulate": args.simulate, "seed": args.seed}

    simulate_mode = bool(payload.get("simulate", True))
    try:
        out = simulate(payload) if simulate_mode else real(payload)
    except Exception as e:
        out = {"ok": False, "error": f"run.py 内部错误: {e!r}"}

    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({"archetype": ARCHETYPE, "brain": BRAIN, "skill": SKILL})
    json.dump(out, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return 0

if __name__ == "__main__":
    sys.exit(main())
